                    fill="none"
                    strokeWidth="5"
                    stroke="white"
                    strokeDasharray="0px 10000px"
                    d="M 0, 20 a 20, 20 0 1,0 40,0 a 20, 20 0 1,0 -40,0"
                    style={{
                        pathLength,
                        rotate: 90,
                        translateX: 5,
                        translateY: 5,
                        scaleX: -1, // Reverse direction of line animation
                    }}
                />
                <motion.path
                    fill="none"
                    strokeWidth="5"
                    stroke="white"
                    d="M14,26 L 22,33 L 35,16"
                    initial={false}
                    strokeDasharray="0px 10000px"
                    animate={{ pathLength: isComplete ? 1 : 0 }}
                />
            </svg>
        </>
    )
}

